<script setup>
import { computed, onMounted, reactive, ref } from "vue"; import UserLayout from "../../layouts/UserLayout.vue"; import MaterialCard from "../../components/MaterialCard.vue"; import { materialService, requestService } from "../../services/api";
const materials = ref([]), loading = ref(true), error = ref(""), selected = ref(null), toast = ref(""); const filters = reactive({ search: "", category: "", status: "" }); const form = reactive({ quantite: 1, type_emprunt: "temporaire", date_debut: "", date_fin_prevue: "", motif: "" });
const categories = ["Ordinateur", "Écran", "Imprimante", "Accessoire", "Téléphone", "Réseau", "Autre"];
const filtered = computed(() => materials.value.filter((item) => (!filters.search || `${item.nom} ${item.description || ""}`.toLowerCase().includes(filters.search.toLowerCase())) && (!filters.category || item.categorie === filters.category) && (!filters.status || item.statut === filters.status)));
const load = async () => { loading.value = true; error.value = ""; try { materials.value = (await materialService.list()).data; } catch (exception) { error.value = exception.message; } finally { loading.value = false; } };
const openRequest = (material) => { selected.value = material; Object.assign(form, { quantite: 1, type_emprunt: "temporaire", date_debut: "", date_fin_prevue: "", motif: "" }); document.getElementById("request-modal").showModal(); };
const submit = async () => { if (!form.motif.trim()) { error.value = "Le motif est obligatoire."; return; } if (form.quantite > selected.value.quantite_disponible) { error.value = "La quantité dépasse le stock disponible."; return; } try { await requestService.create({ ...form, materiel_id: selected.value.id, quantite: Number(form.quantite), date_debut: form.date_debut || null, date_fin_prevue: form.date_fin_prevue || null }); document.getElementById("request-modal").close(); toast.value = "Votre demande a été envoyée."; await load(); setTimeout(() => toast.value = "", 3500); } catch (exception) { error.value = exception.message; } };
onMounted(load);
</script>
<template><UserLayout><section class="bg-[#f1f6f1] py-14 text-center"><p class="text-sm font-semibold uppercase tracking-[.2em] text-[#3f7452]">InfoTech</p><h1 class="mt-2 text-4xl font-bold text-slate-800">Catalogue du matériel</h1><p class="mt-3 text-slate-500">Consultez les équipements disponibles et effectuez une demande d'emprunt.</p></section><section class="mx-auto grid max-w-7xl gap-8 px-5 py-10 lg:grid-cols-[220px_1fr]"><aside class="space-y-6 border-r border-slate-100 pr-5"><div><h2 class="font-semibold">Filtrer les équipements</h2><input v-model="filters.search" class="input input-sm input-bordered mt-3 w-full" placeholder="Rechercher…"></div><fieldset><legend class="mb-2 text-sm font-semibold">Catégorie</legend><label v-for="category in categories" :key="category" class="flex cursor-pointer items-center gap-2 py-1 text-sm"><input v-model="filters.category" type="radio" :value="category" class="radio radio-xs"><span>{{ category }}</span></label><button class="mt-2 text-xs text-[#17482d] underline" @click="filters.category = ''">Toutes les catégories</button></fieldset><fieldset><legend class="mb-2 text-sm font-semibold">Disponibilité</legend><label v-for="status in ['disponible', 'maintenance']" :key="status" class="flex items-center gap-2 py-1 text-sm"><input v-model="filters.status" type="radio" :value="status" class="radio radio-xs"><span class="capitalize">{{ status }}</span></label><button class="mt-2 text-xs text-[#17482d] underline" @click="filters.status = ''">Tous les statuts</button></fieldset></aside><div><div class="mb-6 flex items-center justify-between"><p class="text-sm text-slate-500"><strong class="text-slate-700">{{ filtered.length }}</strong> équipement(s) affiché(s)</p><button class="btn btn-ghost btn-sm" @click="load">Actualiser</button></div><div v-if="loading" class="py-20 text-center"><span class="loading loading-spinner loading-md text-[#17482d]"></span><p class="mt-3 text-sm text-slate-500">Chargement des matériels…</p></div><div v-else-if="error" class="alert alert-error">{{ error }}</div><div v-else-if="!filtered.length" class="rounded-2xl border border-dashed p-12 text-center text-slate-500">Aucun matériel ne correspond à vos filtres.</div><div v-else class="grid gap-5 sm:grid-cols-2 xl:grid-cols-3"><MaterialCard v-for="material in filtered" :key="material.id" :material="material" @request="openRequest" /></div></div></section><div v-if="toast" class="toast toast-end"><div class="alert alert-success">{{ toast }}</div></div><dialog id="request-modal" class="modal"><div class="modal-box"><form method="dialog"><button class="btn btn-circle btn-ghost btn-sm absolute right-3 top-3">✕</button></form><h3 class="text-xl font-bold">Demander ce matériel</h3><p class="mt-1 text-sm text-slate-500">{{ selected?.nom }} · {{ selected?.quantite_disponible }} disponible(s)</p><form class="mt-5 grid gap-3" @submit.prevent="submit"><label class="form-control"><span class="label-text">Quantité</span><input v-model.number="form.quantite" type="number" min="1" :max="selected?.quantite_disponible" class="input input-bordered" required></label><select v-model="form.type_emprunt" class="select select-bordered"><option value="temporaire">Emprunt temporaire</option><option value="definitif">Emprunt définitif</option></select><input v-model="form.date_debut" type="date" class="input input-bordered"><input v-model="form.date_fin_prevue" type="date" class="input input-bordered"><textarea v-model="form.motif" class="textarea textarea-bordered" placeholder="Motif de la demande" required></textarea><button class="btn border-0 bg-[#17482d] text-white">Envoyer la demande</button></form></div></dialog></UserLayout></template>
